/* Tokens for good — dashboard.js
 *
 * Fetches data.json (generated by `tfg pages-build`) and instantiates a
 * handful of Chart.js v4 charts plus a KPI strip.
 *
 * Kept small on purpose: no build step, no framework. Just fetch + DOM.
 */

const KPIs = [
  { id: 'helpful_rate',  label: 'Helpful-signal rate', kind: 'percent_rate' },
  { id: 'total_prs',     label: 'PRs opened',          kind: 'count' },
  { id: 'merged',        label: 'Merged',              kind: 'count' },
  { id: 'closed',        label: 'Closed (no merge)',   kind: 'count' },
  { id: 'open',          label: 'Still open',          kind: 'count' },
  { id: 'opt_outs',      label: 'Opt-outs honored',    kind: 'count' },
];

const PALETTE = {
  primary:  '#3b82f6',
  positive: '#22c55e',
  negative: '#ef4444',
  neutral:  '#9ca3af',
  draft:    '#fbbf24',
  grid:     '#e5e7eb',
};

function fmtNumber(n) { return (n == null) ? '—' : new Intl.NumberFormat().format(n); }
function fmtPercent(r) { return (r == null) ? 'n/a' : `${Math.round(r * 100)}%`; }

function kpiValue(data, k) {
  const kpi = data.kpi || {};
  switch (k.id) {
    case 'helpful_rate': return fmtPercent(kpi.helpful_signal_rate);
    case 'total_prs':    return fmtNumber(kpi.total_prs);
    case 'merged':       return fmtNumber(kpi.merged);
    case 'closed':       return fmtNumber(kpi.closed_unmerged);
    case 'open':         return fmtNumber(kpi.still_open);
    case 'opt_outs':     return fmtNumber((data.opt_outs || {}).count || 0);
    default: return '—';
  }
}

function kpiSub(data, k) {
  const kpi = data.kpi || {};
  if (k.id === 'helpful_rate') {
    const decided = (kpi.helpful_count || 0) + (kpi.unhelpful_count || 0);
    return `${kpi.helpful_count || 0}/${decided} decided`;
  }
  if (k.id === 'opt_outs') {
    const oo = data.opt_outs || {};
    if (oo.most_recent && oo.most_recent.repo) {
      return `last: ${oo.most_recent.repo}`;
    }
    return 'none yet';
  }
  return null;
}

function renderKpi(data) {
  const root = document.getElementById('kpi');
  root.innerHTML = '';
  KPIs.forEach(k => {
    const card = document.createElement('div');
    card.className = 'kpi-card';
    const sub = kpiSub(data, k);
    card.innerHTML = `
      <h3>${k.label}</h3>
      <div class="big-number">${kpiValue(data, k)}</div>
      ${sub ? `<div class="sub">${sub}</div>` : ''}
    `;
    root.appendChild(card);
  });
}

function chartMergeTrend(rows) {
  const ctx = document.getElementById('merge-trend');
  if (!rows || rows.length === 0) {
    ctx.replaceWith(emptyState('No weekly data yet.'));
    return;
  }
  const labels = rows.map(r => r.week);
  const rates  = rows.map(r => r.merge_rate == null ? null : Math.round(r.merge_rate * 100));
  const decided = rows.map(r => r.decided);
  new Chart(ctx, {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: 'Merge rate (%)',
          data: rates,
          borderColor: PALETTE.primary,
          backgroundColor: PALETTE.primary + '33',
          tension: 0.2,
          yAxisID: 'y',
          spanGaps: true,
        },
        {
          label: 'Decided PRs',
          data: decided,
          type: 'bar',
          backgroundColor: PALETTE.neutral + '88',
          yAxisID: 'y1',
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: { beginAtZero: true, max: 100, title: { display: true, text: 'Merge rate (%)' }, grid: { color: PALETTE.grid } },
        y1: { beginAtZero: true, position: 'right', title: { display: true, text: 'Decided PRs' }, grid: { drawOnChartArea: false } },
        x: { grid: { color: PALETTE.grid } },
      },
    },
  });
}

function chartByType(rows) {
  const ctx = document.getElementById('by-type');
  if (!rows || rows.length === 0) {
    ctx.replaceWith(emptyState('No contribution-type data yet.'));
    return;
  }
  const labels = rows.map(r => r.contribution_type);
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [
        { label: 'merged', data: rows.map(r => r.merged || 0), backgroundColor: PALETTE.positive },
        { label: 'closed', data: rows.map(r => r.closed || 0), backgroundColor: PALETTE.negative },
        { label: 'open',   data: rows.map(r => r.open   || 0), backgroundColor: PALETTE.primary },
        { label: 'draft',  data: rows.map(r => r.draft  || 0), backgroundColor: PALETTE.draft },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: { stacked: true, grid: { color: PALETTE.grid } },
        y: { stacked: true, beginAtZero: true, grid: { color: PALETTE.grid } },
      },
    },
  });
}

function chartByModel(rows) {
  const ctx = document.getElementById('by-model');
  if (!rows || rows.length === 0) {
    ctx.replaceWith(emptyState('No per-model breakdown yet.'));
    return;
  }
  const labels = rows.map(r => r.model);
  const rates  = rows.map(r => r.n_decided ? Math.round(100 * (r.merged || 0) / r.n_decided) : 0);
  const totals = rows.map(r => r.n);
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [
        { label: 'Merge rate (%)', data: rates,  backgroundColor: PALETTE.positive, yAxisID: 'y' },
        { label: 'Total PRs',      data: totals, backgroundColor: PALETTE.neutral + '88', yAxisID: 'y1', type: 'line' },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y:  { beginAtZero: true, max: 100, title: { display: true, text: 'Merge rate (%)' }, grid: { color: PALETTE.grid } },
        y1: { beginAtZero: true, position: 'right', title: { display: true, text: 'Total PRs' }, grid: { drawOnChartArea: false } },
      },
    },
  });
}

function chartFriendly(rows) {
  const ctx = document.getElementById('friendly');
  if (!rows || rows.length === 0) {
    ctx.replaceWith(emptyState('No friendly-repo affinity data yet. Score builds up as we observe merges and thank-you signals.'));
    return;
  }
  const labels = rows.map(r => `${r.repo} (${r.contribution_type})`);
  const scores = rows.map(r => r.score);
  new Chart(ctx, {
    type: 'bar',
    data: {
      labels,
      datasets: [{ label: 'Affinity score', data: scores, backgroundColor: PALETTE.primary }],
    },
    options: {
      indexAxis: 'y',
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: { beginAtZero: true, grid: { color: PALETTE.grid } },
        y: { grid: { color: PALETTE.grid } },
      },
    },
  });
}

function emptyState(msg) {
  const div = document.createElement('div');
  div.className = 'note';
  div.style.padding = '1rem';
  div.style.background = '#fafafa';
  div.style.borderRadius = '6px';
  div.textContent = msg;
  return div;
}

function fmtTimestamp(iso) {
  try {
    const d = new Date(iso);
    return d.toISOString().replace('T', ' ').replace('Z', ' UTC');
  } catch (e) {
    return iso || 'unknown';
  }
}

async function main() {
  const lastUpdatedEl = document.getElementById('last-updated');
  let data;
  try {
    const resp = await fetch('./data.json', { cache: 'no-store' });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    data = await resp.json();
  } catch (err) {
    lastUpdatedEl.textContent = 'failed to load data.json';
    console.error(err);
    return;
  }
  lastUpdatedEl.textContent = fmtTimestamp(data.generated_at);

  renderKpi(data);
  chartMergeTrend(data.merge_rate_by_week);
  chartByType(data.by_type);
  chartByModel(data.by_model);
  chartFriendly(data.top_friendly);
}

main();
